/**
 * @route   PUT /api/plans/:id
 * @access  Private
 * @desc    Update a plan
 * @param   {String} id - Plan ID
 * @body    {Object} Update fields (name, description, startDate, endDate, budget, status)
 * @returns {Object} Updated plan object
 */
exports.updatePlan = async (req, res) => {
  try {
    const { id } = req.params;
    const { name, description, startDate, endDate, budget, status } = req.body;

    // Validate ID format
    if (!id.match(/^[0-9a-fA-F]{24}$/)) {
      return res.status(400).json({
        success: false,
        message: 'Invalid plan ID format'
      });
    }

    // Validate update payload
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        success: false,
        message: 'Validation failed',
        errors: errors.array()
      });
    }

    // Fetch plan
    const plan = await Plan.findById(id);

    if (!plan) {
      return res.status(404).json({
        success: false,
        message: 'Plan not found'
      });
    }

    // Authorization check
    if (plan.owner.toString() !== req.user.id) {
      return res.status(403).json({
        success: false,
        message: 'Unauthorized to update this plan'
      });
    }

    // Business logic: Prevent updates to completed plans
    if (plan.status === 'completed' && status !== 'completed') {
      return res.status(422).json({
        success: false,
        message: 'Cannot modify a completed plan'
      });
    }

    // Validate date range if both dates provided
    if (startDate && endDate && new Date(startDate) >= new Date(endDate)) {
      return res.status(422).json({
        success: false,
        message: 'Invalid date range: end date must be after start date'
      });
    }

    // Update fields
    if (name) plan.name = name;
    if (description) plan.description = description;
    if (startDate) plan.startDate = startDate;
    if (endDate) plan.endDate = endDate;
    if (budget !== undefined) plan.budget = budget;
    if (status) plan.status = status;
    plan.updatedAt = new Date();
    plan.updatedBy = req.user.id;

    const updatedPlan = await plan.save();

    logger.info(`Plan updated: ${id} by user ${req.user.id}`);

    return res.status(200).json({
      success: true,
      message: 'Plan updated successfully',
      data: updatedPlan
    });
  } catch (error) {
    logger.error(`Update plan error: ${error.message}`);
    return res.status(500).json({
      success: false,
      message: 'Internal server error',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
};

