  /**
   * Calculate duration in milliseconds
   */
  getDuration(): number | null {
    if (!this.startedAt) return null;
    const endTime = this.completedAt || new Date();
    return endTime.getTime() - this.startedAt.getTime();
  }

  /**
   * Check if run is in terminal state
   */
  isTerminal(): boolean {
    return this.status === RunStatus.COMPLETED || this.status === RunStatus.FAILED;
  }

  /**
   * Validate status transition
   */
  static validateTransition(currentStatus: RunStatus, newStatus: RunStatus): boolean {
    const validTransitions: Record<RunStatus, RunStatus[]> = {
