      [RunStatus.EXECUTING]: [RunStatus.COMPLETED, RunStatus.FAILED],
      [RunStatus.COMPLETED]: [],
      [RunStatus.FAILED]: [],
    };

    return validTransitions[currentStatus]?.includes(newStatus) ?? false;
  }
