      if (fieldsToRedact.some(field => key.toLowerCase().includes(field.toLowerCase()))) {
        target[key] = '[REDACTED]';
      } else if (typeof target[key] === 'object' && target[key] !== null) {
        walk(target[key]);
      }
    }
  };
  walk(redacted);
  return redacted;
}

/**
 * Utility function to safely serialize request/response bodies
 */
function serializeBody(body: any, maxSize: number, redactFields: string[]): any {
  try {
    if (!body) return undefined;

    const serialized = typeof body === 'string' ? body : JSON.stringify(body);

    if (serialized.length > maxSize) {
      return `[Body truncated - original size: ${serialized.length} bytes]`;
    }

    const parsed = typeof body === 'string' ? JSON.parse(serialized) : body;
    return redactSensitiveData(parsed, redactFields);
  } catch (error) {
    return `[Unable to serialize body: ${(error as Error).message}]`;
  }
}

/**
 * Check if request should be sampled for body logging
 */
function shouldSampleBody(config: BodySamplingConfig, path: string): boolean {
  // Never sample excluded paths
  if (config.excludePaths.some(pattern => pattern.test(path))) {
    return false;
  }

  // Sample based on configured rate
  return Math.random() < config.sampleRate;
}

/**
 * Main request logging middleware
 */
function requestLoggingMiddleware(samplingConfig: BodySamplingConfig = defaultSamplingConfig) {
  return (req: Request, res: Response, next: NextFunction) => {
    const requestId = req.headers['x-request-id'] as string || uuidv4();
    const correlationId = req.headers['x-correlation-id'] as string || requestId;
    const startTime = Date.now();

    // Store in async context for access throughout request lifecycle
    requestContext.run(
      {
        requestId,
        startTime,
        correlationId,
        userId: (req as any).userId // Assuming auth middleware sets this
      },
      () => {
        // Set response headers for tracing
        res.setHeader('X-Request-ID', requestId);
        res.setHeader('X-Correlation-ID', correlationId);

        // Capture request body if sampling enabled
        let requestBody: any = undefined;
        const shouldSample = samplingConfig.enabled && shouldSampleBody(samplingConfig, req.path);

        if (shouldSample && req.method !== 'GET' && req.method !== 'HEAD') {
          requestBody = serializeBody(
            req.body,
            samplingConfig.maxBodySize,
            samplingConfig.excludeFields
          );
        }

        // Capture original response.json to log response body
        let responseBody: any = undefined;
        const originalJson = res.json.bind(res);
        const originalSend = res.send.bind(res);

        res.json = function(body: any) {
          if (shouldSample) {
            responseBody = serializeBody(
              body,
              samplingConfig.maxBodySize,
              samplingConfig.excludeFields
            );
          }
          return originalJson(body);
        };

        res.send = function(body: any) {
          if (shouldSample && typeof body === 'object') {
            responseBody = serializeBody(
              body,
              samplingConfig.maxBodySize,
              samplingConfig.excludeFields
            );
          }
          return originalSend(body);
        };

        // Log request initiation
        logger.info('Incoming request', {
          requestId,
          correlationId,
          method: req.method,
          path: req.path,
          query: req.query,
          userAgent: req.get('user-agent'),
          ip: req.ip || req.socket.remoteAddress,
          ...(requestBody && { requestBody })
        } as RequestLogMetadata);

        // Listen for response finish
        res.on('finish', () => {
          const duration = Date.now() - startTime;
          const metadata: RequestLogMetadata = {
            requestId,
            correlationId,
            method: req.method,
            path: req.path,
            statusCode: res.statusCode,
            duration,
            userId: (req as any).userId,
            userAgent: req.get('user-agent'),
            ip: req.ip || req.socket.remoteAddress,
            ...(requestBody && { requestBody }),
            ...(responseBody && { responseBody })
          };

          // Log based on status code
          if (res.statusCode >= 500) {
            logger.error('Request completed with server error', metadata);
          } else if (res.statusCode >= 400) {
            logger.warn('Request completed with client error', metadata);
          } else {
            logger.info('Request completed', metadata);
          }
        });

        // Listen for errors
        res.on('close', () => {
          if (!res.writableEnded) {
            const duration = Date.now() - startTime;
            logger.warn('Request connection closed prematurely', {
              requestId,
              correlationId,
              method: req.method,
              path: req.path,
              duration
            } as RequestLogMetadata);
          }
        });

        next();
      }
    );
  };
}

/**
 * Error logging middleware - should be placed after other middlewares
 */
function errorLoggingMiddleware(err: any, req: Request, res: Response, next: NextFunction) {
  const context = requestContext.getStore();
  const requestId = context?.requestId || 'unknown';
  const correlationId = context?.correlationId || requestId;
  const duration = context ? Date.now() - context.startTime : undefined;

  logger.error('Request error', {
    requestId,
    correlationId,
    method: req.method,
    path: req.path,
    duration,
    error: {
      message: err.message,
      stack: err.stack,
      code: err.code,
      statusCode: err.statusCode || 500
    }
  } as RequestLogMetadata & { error: any });

  // Ensure error response includes request ID for tracing
  res.setHeader('X-Request-ID', requestId);
  res.setHeader('X-Correlation-ID', correlationId);

  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: {
      message: process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message,
      requestId,
      correlationId
    }
  });
}

/**
 * Utility function to get current request context from anywhere in the async chain
 */
function getRequestContext() {
  return requestContext.getStore();
}

/**
 * Utility function to log with automatic correlation
 */
function logWithContext(level: 'info' | 'warn' | 'error', message: string, meta?: any) {
  const context = getRequestContext();
  logger.log(level, message, {
    ...meta,
    requestId: context?.requestId,
    correlationId: context?.correlationId,
    userId: context?.userId
  });
}

export {
  requestLoggingMiddleware,
  errorLoggingMiddleware,
  getRequestContext,
  logWithContext,
  logger,
  BodySamplingConfig,
  RequestLogMetadata,
  defaultSamplingConfig
};"
