// Helper functions
function calculateOverallStatus(checks) {
  const statuses = checks.map(c => c.status);
  if (statuses.includes('unhealthy')) return 'unhealthy';
  if (statuses.includes('degraded')) return 'degraded';
  return 'healthy';
}

function formatUptime(seconds) {
  const days = Math.floor(seconds / 86400);
  const hours = Math.floor((seconds % 86400) / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  return `${days}d ${hours}h ${minutes}m`;
}

async function checkDatabaseConnection() {
  try {
    const startTime = Date.now();
    // Assumes db connection pool available globally
    const result = await global.db.query('SELECT 1');
    return {
      status: 'healthy',
      host: process.env.DB_HOST,
      pool_active: global.db.pool._activeCount,
      pool_idle: global.db.pool._idleCount,
      connection_time_ms: Date.now() - startTime
    };
  } catch (error) {
    return {
      status: 'unhealthy',
      host: process.env.DB_HOST,
      error: error.message,
      pool_active: global.db?.pool?._activeCount || 0,
      pool_idle: global.db?.pool?._idleCount || 0
    };
  }
}

async function checkCacheConnection() {
  try {
    const startTime = Date.now();
    // Assumes Redis/cache client available globally
    await global.cache.ping();
    const info = await global.cache.info('memory');
    return {
      status: 'healthy',
      host: process.env.CACHE_HOST,
      memory_used_mb: (parseInt(info.used_memory) / 1024 / 1024).toFixed(2),
      keys_count: await global.cache.dbsize(),
      connection_time_ms: Date.now() - startTime
    };
  } catch (error) {
    return {
      status: 'unhealthy',
      host: process.env.CACHE_HOST,
      error: error.message
    };
  }
}

